src/ProgrammableFeePoolInitializerV2.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {
    ProgrammableCurrency,
    ProgrammableFeeVaultV1,
    ProgrammableHookPermissions,
    ProgrammablePoolKey
} from "./ProgrammableAdditiveFeeHookV1.sol";
import {
    IProgrammableFeePolicyProfileV2,
    PROGRAMMABLE_FEE_ASSET_MODE_V2,
    PROGRAMMABLE_FEE_BASIS_V2,
    PROGRAMMABLE_FEE_POLICY_CHAIN_ID_V2,
    PROGRAMMABLE_FEE_POLICY_DENOMINATOR_PPM_V2,
    PROGRAMMABLE_FEE_POLICY_RATE_PPM_V2,
    PROGRAMMABLE_FEE_POLICY_RECIPIENT_V2,
    PROGRAMMABLE_FEE_POLICY_REQUIRED_HOOK_FLAGS_V2,
    PROGRAMMABLE_FEE_POLICY_VERSION_V2,
    PROGRAMMABLE_FEE_VAULT_V2_RUNTIME_CODE_HASH,
    PROGRAMMABLE_ISOLATED_AFTER_SWAP_PROFILE_V2,
    PROGRAMMABLE_LAUNCH_TOKEN_V2_RUNTIME_CODE_HASH,
    PROGRAMMABLE_ZERO_CUSTOM_PROFILE_V2,
    ProgrammableCompositionV2,
    programmableCompositionHashV2,
    programmableDeploymentProfileHashV2,
    programmableFeePolicyIdV2,
    programmableModuleCodeIsSafeV2
} from "./ProgrammableAdditiveFeeHookV2.sol";
import {
    PROGRAMMABLE_CANONICAL_GRAPH_DEPLOYER_RUNTIME_CODE_HASH_V2,
    PROGRAMMABLE_CANONICAL_GRAPH_DEPLOYER_V2,
    PROGRAMMABLE_CANONICAL_POOL_MANAGER_RUNTIME_CODE_HASH_V2,
    PROGRAMMABLE_CANONICAL_POOL_MANAGER_V2,
    ProgrammableFeeVaultV2Core
} from "./ProgrammableFeeVaultV2.sol";

bytes32 constant PROGRAMMABLE_ZERO_CUSTOM_FEE_HOOK_V2_RUNTIME_CODE_HASH =
    0x10267e0a2727fa81bc905bbe17f8d573d98ffea9ba5ef4dfec29a3fd4c582d46;
bytes32 constant PROGRAMMABLE_ISOLATED_FEE_HOOK_V2_RUNTIME_CODE_HASH =
    0xe2bbc60d8e8fbe2fa16576f02785445063acf342cdeb1acfea1539d7cb96f067;

interface IProgrammableV4PoolInitializerManagerV2 {
    function initialize(ProgrammablePoolKey calldata key, uint160 sqrtPriceX96) external returns (int24 tick);
}

interface IProgrammableFeeHookBindingV2 is IProgrammableFeePolicyProfileV2 {
    function poolManager() external view returns (address);
    function graphDeployer() external view returns (address);
    function platformFeeVault() external view returns (ProgrammableFeeVaultV1);
    function platformFeeAccrualContextHash() external view returns (bytes32);
    function PLATFORM_FEE_PPM() external pure returns (uint24);
    function FEE_DENOMINATOR_PPM() external pure returns (uint24);
    function PLATFORM_FEE_RECIPIENT() external pure returns (address);
    function REQUIRED_HOOK_FLAGS() external pure returns (uint160);
    function getHookPermissions() external pure returns (ProgrammableHookPermissions memory permissions);
    function poolBindingComplete() external view returns (bool);
    function poolInitialized() external view returns (bool);
    function authorizedInitializer() external view returns (address);
    function authorizedInitializerRuntimeCodeHash() external view returns (bytes32);
    function boundPoolId() external view returns (bytes32);
    function boundInitialSqrtPriceX96() external view returns (uint160);
    function boundToken() external view returns (address);
    function boundHookRuntimeCodeHash() external view returns (bytes32);
    function boundVaultRuntimeCodeHash() external view returns (bytes32);
    function boundTokenRuntimeCodeHash() external view returns (bytes32);
    function deploymentProfileHash() external view returns (bytes32);
    function compositionHash() external view returns (bytes32);
}

abstract contract ProgrammableFeePoolInitializerV2Core {
    uint24 private constant DYNAMIC_FEE_FLAG = 0x800000;
    uint24 public constant MAX_STATIC_LP_FEE_PPM = 100_000;
    uint160 private constant ALL_HOOK_MASK = (1 << 14) - 1;

    address public poolManager;
    address public graphDeployer;
    ProgrammableFeeVaultV2Core public platformFeeVault;
    IProgrammableFeeHookBindingV2 public feeHook;
    address public token;
    uint24 public poolFee;
    int24 public tickSpacing;
    uint160 public initialSqrtPriceX96;

    bool public initialized;
    bytes32 public initializedPoolId;
    int24 public initializedTick;

    error AdapterCodeHashMismatch(bytes32 sealedCodeHash, bytes32 actualCodeHash);
    error AddressMismatch(bytes32 field, address expected, address actual);
    error AlreadyInitialized();
    error CompositionMismatch(bytes32 expected, bytes32 actual);
    error FeePolicyMismatch(bytes32 field, bytes32 expected, bytes32 actual);
    error InvalidAddress(bytes32 field, address actual);
    error InvalidCustomModuleCodeHash(bytes32 expected, bytes32 actual);
    error InvalidCustomModuleOpcode(address module);
    error InvalidHookAddressFlags(uint160 actual, uint160 required);
    error InvalidHookPermissions();
    error InvalidInitialSqrtPrice(uint160 actual);
    error InvalidPoolFee(uint24 actual, uint24 maximum);
    error InvalidRuntimeTemplate(address target, bytes32 actual);
    error InvalidTickSpacing(int24 actual);
    error PoolBindingMismatch(bytes32 field, bytes32 expected, bytes32 actual);
    error RuntimeCodeHashMismatch(address target, bytes32 expected, bytes32 actual);
    error SealMismatch(address expectedHook, address actualHook, address bindingAuthority);
    error UnauthorizedGraphDeployer(address caller);
    error UnsupportedFeePolicyChain(uint256 actual, uint256 required);

    event ProgrammableFeePoolInitialized(
        bytes32 indexed poolId,
        address indexed hook,
        address indexed token,
        bytes32 feePolicyId,
        uint24 poolFee,
        int24 tickSpacing,
        uint160 initialSqrtPriceX96,
        int24 initializedTick
    );
    event ProgrammableFeeCompositionObserved(
        bytes32 indexed poolId,
        bytes32 indexed deploymentProfileHash,
        bytes32 indexed compositionHash,
        bytes32 hookRuntimeCodeHash,
        bytes32 vaultRuntimeCodeHash,
        bytes32 initializerRuntimeCodeHash,
        bytes32 tokenRuntimeCodeHash
    );

    constructor(
        address poolManager_,
        address graphDeployer_,
        ProgrammableFeeVaultV2Core platformFeeVault_,
        IProgrammableFeeHookBindingV2 feeHook_,
        address token_,
        uint24 poolFee_,
        int24 tickSpacing_,
        uint160 initialSqrtPriceX96_
    ) {
        _requireContract("poolManager", poolManager_);
        _requireContract("graphDeployer", graphDeployer_);
        _requireContract("platformFeeVault", address(platformFeeVault_));
        _requireContract("feeHook", address(feeHook_));
        _requireContract("token", token_);
        if (poolFee_ & DYNAMIC_FEE_FLAG != 0 || poolFee_ > MAX_STATIC_LP_FEE_PPM) {
            revert InvalidPoolFee(poolFee_, MAX_STATIC_LP_FEE_PPM);
        }
        uint160 hookFlags = uint160(address(feeHook_)) & ALL_HOOK_MASK;
        if (hookFlags != PROGRAMMABLE_FEE_POLICY_REQUIRED_HOOK_FLAGS_V2) {
            revert InvalidHookAddressFlags(hookFlags, PROGRAMMABLE_FEE_POLICY_REQUIRED_HOOK_FLAGS_V2);
        }
        if (tickSpacing_ <= 0 || tickSpacing_ > 32_767) revert InvalidTickSpacing(tickSpacing_);
        if (initialSqrtPriceX96_ == 0) revert InvalidInitialSqrtPrice(initialSqrtPriceX96_);

        poolManager = poolManager_;
        graphDeployer = graphDeployer_;
        platformFeeVault = platformFeeVault_;
        feeHook = feeHook_;
        token = token_;
        poolFee = poolFee_;
        tickSpacing = tickSpacing_;
        initialSqrtPriceX96 = initialSqrtPriceX96_;
    }

    function poolKey() public view returns (ProgrammablePoolKey memory key) {
        key = ProgrammablePoolKey({
            currency0: ProgrammableCurrency.wrap(address(0)),
            currency1: ProgrammableCurrency.wrap(token),
            fee: poolFee,
            tickSpacing: tickSpacing,
            hooks: address(feeHook)
        });
    }

    function poolId() public view returns (bytes32) {
        return keccak256(abi.encode(poolKey()));
    }

    function expectedVaultRuntimeCodeHash() external view returns (bytes32) {
        return _vaultRuntimeCodeHash();
    }

    function expectedZeroCustomHookRuntimeCodeHash() external view returns (bytes32) {
        return _zeroCustomHookRuntimeCodeHash();
    }

    function expectedIsolatedHookRuntimeCodeHash() external view returns (bytes32) {
        return _isolatedHookRuntimeCodeHash();
    }

    function expectedTokenRuntimeCodeHash() external view returns (bytes32) {
        return _tokenRuntimeCodeHash();
    }

    function canonicalPoolManagerRuntimeCodeHash() external view returns (bytes32) {
        return _canonicalPoolManagerRuntimeCodeHash();
    }

    function canonicalGraphDeployerRuntimeCodeHash() external view returns (bytes32) {
        return _canonicalGraphDeployerRuntimeCodeHash();
    }

    function initializePool() external returns (bytes32 createdPoolId, int24 tick) {
        if (msg.sender != graphDeployer) revert UnauthorizedGraphDeployer(msg.sender);
        if (initialized) revert AlreadyInitialized();
        initialized = true;
        _requireCanonicalEnvironment();
        (bytes32 profile, bytes32 hookRuntime, bytes32 vaultRuntime) = _requireCanonicalComposition();

        ProgrammablePoolKey memory key = poolKey();
        createdPoolId = keccak256(abi.encode(key));
        tick = IProgrammableV4PoolInitializerManagerV2(poolManager).initialize(key, initialSqrtPriceX96);
        if (!feeHook.poolInitialized()) {
            revert PoolBindingMismatch("hook.poolInitialized", bytes32(uint256(1)), bytes32(0));
        }
        initializedPoolId = createdPoolId;
        initializedTick = tick;

        emit ProgrammableFeePoolInitialized(
            createdPoolId,
            address(feeHook),
            token,
            programmableFeePolicyIdV2(profile),
            poolFee,
            tickSpacing,
            initialSqrtPriceX96,
            tick
        );
        emit ProgrammableFeeCompositionObserved(
            createdPoolId,
            feeHook.deploymentProfileHash(),
            feeHook.compositionHash(),
            hookRuntime,
            vaultRuntime,
            address(this).codehash,
            token.codehash
        );
    }

    function _requireCanonicalEnvironment() private view {
        if (block.chainid != PROGRAMMABLE_FEE_POLICY_CHAIN_ID_V2) {
            revert UnsupportedFeePolicyChain(block.chainid, PROGRAMMABLE_FEE_POLICY_CHAIN_ID_V2);
        }
        _requireRuntimeCodeHash(poolManager, _canonicalPoolManagerRuntimeCodeHash());
        _requireRuntimeCodeHash(graphDeployer, _canonicalGraphDeployerRuntimeCodeHash());
        _requireRuntimeCodeHash(token, _tokenRuntimeCodeHash());
    }

    function _requireCanonicalComposition()
        private
        view
        returns (bytes32 profile, bytes32 hookRuntime, bytes32 vaultRuntime)
    {
        hookRuntime = address(feeHook).codehash;
        vaultRuntime = address(platformFeeVault).codehash;
        bytes32 zeroHookRuntime = _zeroCustomHookRuntimeCodeHash();
        bytes32 isolatedHookRuntime = _isolatedHookRuntimeCodeHash();
        if (hookRuntime == zeroHookRuntime) profile = PROGRAMMABLE_ZERO_CUSTOM_PROFILE_V2;
        else if (hookRuntime == isolatedHookRuntime) profile = PROGRAMMABLE_ISOLATED_AFTER_SWAP_PROFILE_V2;
        else revert InvalidRuntimeTemplate(address(feeHook), hookRuntime);
        bytes32 expectedVaultRuntime = _vaultRuntimeCodeHash();
        if (vaultRuntime != expectedVaultRuntime) {
            revert RuntimeCodeHashMismatch(address(platformFeeVault), expectedVaultRuntime, vaultRuntime);
        }

        address hook = address(feeHook);
        address authority = platformFeeVault.bindingAuthority();
        address sealedHook = platformFeeVault.authorizedAdapter();
        if (authority != address(0) || sealedHook != hook) revert SealMismatch(hook, sealedHook, authority);
        if (platformFeeVault.authorizedAdapterCodeHash() != hookRuntime) {
            revert AdapterCodeHashMismatch(platformFeeVault.authorizedAdapterCodeHash(), hookRuntime);
        }
        _requireAddress("vault.poolManager", poolManager, platformFeeVault.poolManager());
        _requireAddress("hook.poolManager", poolManager, feeHook.poolManager());
        _requireAddress("hook.graphDeployer", graphDeployer, feeHook.graphDeployer());
        _requireAddress("hook.platformFeeVault", address(platformFeeVault), address(feeHook.platformFeeVault()));
        _requireUint(
            "vault.flags", PROGRAMMABLE_FEE_POLICY_REQUIRED_HOOK_FLAGS_V2, platformFeeVault.requiredAdapterFlags()
        );
        _requireUint("vault.rate", PROGRAMMABLE_FEE_POLICY_RATE_PPM_V2, platformFeeVault.PLATFORM_FEE_PPM());
        _requireUint(
            "vault.denominator", PROGRAMMABLE_FEE_POLICY_DENOMINATOR_PPM_V2, platformFeeVault.FEE_DENOMINATOR_PPM()
        );
        _requireAddress(
            "vault.recipient", PROGRAMMABLE_FEE_POLICY_RECIPIENT_V2, platformFeeVault.PLATFORM_FEE_RECIPIENT()
        );
        _requireUint("hook.rate", PROGRAMMABLE_FEE_POLICY_RATE_PPM_V2, feeHook.PLATFORM_FEE_PPM());
        _requireUint("hook.denominator", PROGRAMMABLE_FEE_POLICY_DENOMINATOR_PPM_V2, feeHook.FEE_DENOMINATOR_PPM());
        _requireAddress("hook.recipient", PROGRAMMABLE_FEE_POLICY_RECIPIENT_V2, feeHook.PLATFORM_FEE_RECIPIENT());
        _requireUint("hook.flags", PROGRAMMABLE_FEE_POLICY_REQUIRED_HOOK_FLAGS_V2, feeHook.REQUIRED_HOOK_FLAGS());

        _requirePolicy(profile);
        _requireExactHookPermissions(feeHook.getHookPermissions());
        _requirePoolBinding(profile, hookRuntime, vaultRuntime);
    }

    function _requirePolicy(bytes32 profile) private view {
        _requireUint("policy.version", PROGRAMMABLE_FEE_POLICY_VERSION_V2, feeHook.feePolicyVersion());
        _requireUint("policy.chainId", PROGRAMMABLE_FEE_POLICY_CHAIN_ID_V2, feeHook.feePolicyChainId());
        _requireBytes32("policy.profile", profile, feeHook.feePolicyProfile());
        _requireBytes32("policy.id", programmableFeePolicyIdV2(profile), feeHook.feePolicyId());
        _requireBytes32("policy.basis", PROGRAMMABLE_FEE_BASIS_V2, feeHook.feePolicyBasis());
        _requireBytes32("policy.assetMode", PROGRAMMABLE_FEE_ASSET_MODE_V2, feeHook.feePolicyAssetMode());
        _requireUint("policy.rate", PROGRAMMABLE_FEE_POLICY_RATE_PPM_V2, feeHook.feePolicyRatePpm());
        _requireUint(
            "policy.denominator", PROGRAMMABLE_FEE_POLICY_DENOMINATOR_PPM_V2, feeHook.feePolicyDenominatorPpm()
        );
        _requireAddress("policy.recipient", PROGRAMMABLE_FEE_POLICY_RECIPIENT_V2, feeHook.feePolicyRecipient());
        _requireUint(
            "policy.flags", PROGRAMMABLE_FEE_POLICY_REQUIRED_HOOK_FLAGS_V2, feeHook.feePolicyRequiredHookFlags()
        );
        _requireUint("policy.maxCustomDelta", 0, feeHook.feePolicyMaximumCustomDeltaAbsolute());
    }

    function _requirePoolBinding(bytes32 profile, bytes32 hookRuntime, bytes32 vaultRuntime) private view {
        bytes32 expectedPoolId = poolId();
        if (!feeHook.poolBindingComplete()) {
            revert PoolBindingMismatch("hook.poolBindingComplete", bytes32(uint256(1)), bytes32(0));
        }
        _requireAddress("hook.initializer", address(this), feeHook.authorizedInitializer());
        _requireBytes32(
            "hook.initializerRuntime", address(this).codehash, feeHook.authorizedInitializerRuntimeCodeHash()
        );
        _requireBytes32("hook.poolId", expectedPoolId, feeHook.boundPoolId());
        _requireUint("hook.sqrtPrice", initialSqrtPriceX96, feeHook.boundInitialSqrtPriceX96());
        _requireBytes32("hook.runtime", hookRuntime, feeHook.boundHookRuntimeCodeHash());
        _requireBytes32("vault.runtime", vaultRuntime, feeHook.boundVaultRuntimeCodeHash());
        _requireAddress("hook.token", token, feeHook.boundToken());
        _requireBytes32("token.runtime", token.codehash, feeHook.boundTokenRuntimeCodeHash());

        address customModule = feeHook.feePolicyCustomModule();
        bytes32 customModuleRuntime = feeHook.feePolicyCustomModuleRuntimeCodeHash();
        if (profile == PROGRAMMABLE_ZERO_CUSTOM_PROFILE_V2) {
            if (customModule != address(0) || customModuleRuntime != bytes32(0)) {
                revert InvalidCustomModuleCodeHash(bytes32(0), customModuleRuntime);
            }
        } else {
            _requireContract("policy.customModule", customModule);
            bytes32 actualModuleRuntime = customModule.codehash;
            if (customModuleRuntime != actualModuleRuntime) {
                revert InvalidCustomModuleCodeHash(customModuleRuntime, actualModuleRuntime);
            }
            if (!programmableModuleCodeIsSafeV2(customModule.code)) revert InvalidCustomModuleOpcode(customModule);
        }

        bytes32 tokenRuntime = token.codehash;
        bytes32 expectedProfileHash = programmableDeploymentProfileHashV2(
            profile, hookRuntime, vaultRuntime, tokenRuntime, customModuleRuntime
        );
        _requireBytes32("hook.deploymentProfile", expectedProfileHash, feeHook.deploymentProfileHash());
        bytes32 expectedComposition = programmableCompositionHashV2(
            ProgrammableCompositionV2({
                deploymentProfileHash: expectedProfileHash,
                hook: address(feeHook),
                hookRuntimeCodeHash: hookRuntime,
                vault: address(platformFeeVault),
                vaultRuntimeCodeHash: vaultRuntime,
                initializer: address(this),
                initializerRuntimeCodeHash: address(this).codehash,
                poolId: expectedPoolId,
                initialSqrtPriceX96: initialSqrtPriceX96,
                token: token,
                tokenRuntimeCodeHash: tokenRuntime,
                customModule: customModule,
                customModuleRuntimeCodeHash: customModuleRuntime,
                customDeltaAccount: address(0),
                maximumCustomDeltaAbsolute: uint128(0)
            })
        );
        bytes32 actualComposition = feeHook.compositionHash();
        if (actualComposition != expectedComposition) {
            revert CompositionMismatch(expectedComposition, actualComposition);
        }
    }

    function _requireExactHookPermissions(ProgrammableHookPermissions memory permissions) internal pure {
        if (
            !permissions.beforeInitialize || permissions.afterInitialize || permissions.beforeAddLiquidity
                || permissions.afterAddLiquidity || permissions.beforeRemoveLiquidity
                || permissions.afterRemoveLiquidity || permissions.beforeSwap || !permissions.afterSwap
                || permissions.beforeDonate || permissions.afterDonate || permissions.beforeSwapReturnDelta
                || !permissions.afterSwapReturnDelta || permissions.afterAddLiquidityReturnDelta
                || permissions.afterRemoveLiquidityReturnDelta
        ) revert InvalidHookPermissions();
    }

    function _vaultRuntimeCodeHash() internal view virtual returns (bytes32);
    function _zeroCustomHookRuntimeCodeHash() internal view virtual returns (bytes32);
    function _isolatedHookRuntimeCodeHash() internal view virtual returns (bytes32);
    function _tokenRuntimeCodeHash() internal view virtual returns (bytes32);
    function _canonicalPoolManagerRuntimeCodeHash() internal view virtual returns (bytes32);
    function _canonicalGraphDeployerRuntimeCodeHash() internal view virtual returns (bytes32);

    function _requireRuntimeCodeHash(address target, bytes32 expected) private view {
        bytes32 actual = target.codehash;
        if (actual != expected) revert RuntimeCodeHashMismatch(target, expected, actual);
    }

    function _requireContract(bytes32 field, address account) private view {
        if (account == address(0) || account.code.length == 0) revert InvalidAddress(field, account);
    }

    function _requireAddress(bytes32 field, address expected, address actual) private pure {
        if (actual != expected) revert AddressMismatch(field, expected, actual);
    }

    function _requireBytes32(bytes32 field, bytes32 expected, bytes32 actual) private pure {
        if (actual != expected) revert FeePolicyMismatch(field, expected, actual);
    }

    function _requireUint(bytes32 field, uint256 expected, uint256 actual) private pure {
        if (actual != expected) revert FeePolicyMismatch(field, bytes32(expected), bytes32(actual));
    }
}

contract ProgrammableFeePoolInitializerV2 is ProgrammableFeePoolInitializerV2Core {
    constructor(
        ProgrammableFeeVaultV2Core platformFeeVault_,
        IProgrammableFeeHookBindingV2 feeHook_,
        address token_,
        uint24 poolFee_,
        int24 tickSpacing_,
        uint160 initialSqrtPriceX96_
    )
        ProgrammableFeePoolInitializerV2Core(
            PROGRAMMABLE_CANONICAL_POOL_MANAGER_V2,
            PROGRAMMABLE_CANONICAL_GRAPH_DEPLOYER_V2,
            platformFeeVault_,
            feeHook_,
            token_,
            poolFee_,
            tickSpacing_,
            initialSqrtPriceX96_
        )
    { }

    function _vaultRuntimeCodeHash() internal pure override returns (bytes32) {
        return PROGRAMMABLE_FEE_VAULT_V2_RUNTIME_CODE_HASH;
    }

    function _zeroCustomHookRuntimeCodeHash() internal pure override returns (bytes32) {
        return PROGRAMMABLE_ZERO_CUSTOM_FEE_HOOK_V2_RUNTIME_CODE_HASH;
    }

    function _isolatedHookRuntimeCodeHash() internal pure override returns (bytes32) {
        return PROGRAMMABLE_ISOLATED_FEE_HOOK_V2_RUNTIME_CODE_HASH;
    }

    function _tokenRuntimeCodeHash() internal pure override returns (bytes32) {
        return PROGRAMMABLE_LAUNCH_TOKEN_V2_RUNTIME_CODE_HASH;
    }

    function _canonicalPoolManagerRuntimeCodeHash() internal pure override returns (bytes32) {
        return PROGRAMMABLE_CANONICAL_POOL_MANAGER_RUNTIME_CODE_HASH_V2;
    }

    function _canonicalGraphDeployerRuntimeCodeHash() internal pure override returns (bytes32) {
        return PROGRAMMABLE_CANONICAL_GRAPH_DEPLOYER_RUNTIME_CODE_HASH_V2;
    }
}

src/ProgrammableAdditiveFeeHookV1.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @dev Hermetic ABI mirror of the Uniswap v4 types used by this module. The
/// selectors and tuple layouts are identical to v4-core while this canonical
/// source remains independently compilable by the admission engine.
type ProgrammableCurrency is address;
type ProgrammableBalanceDelta is int256;

struct ProgrammablePoolKey {
    ProgrammableCurrency currency0;
    ProgrammableCurrency currency1;
    uint24 fee;
    int24 tickSpacing;
    address hooks;
}

struct ProgrammableSwapParams {
    bool zeroForOne;
    int256 amountSpecified;
    uint160 sqrtPriceLimitX96;
}

struct ProgrammableHookPermissions {
    bool beforeInitialize;
    bool afterInitialize;
    bool beforeAddLiquidity;
    bool afterAddLiquidity;
    bool beforeRemoveLiquidity;
    bool afterRemoveLiquidity;
    bool beforeSwap;
    bool afterSwap;
    bool beforeDonate;
    bool afterDonate;
    bool beforeSwapReturnDelta;
    bool afterSwapReturnDelta;
    bool afterAddLiquidityReturnDelta;
    bool afterRemoveLiquidityReturnDelta;
}

interface IProgrammableV4HookV1 {
    function afterSwap(
        address sender,
        ProgrammablePoolKey calldata key,
        ProgrammableSwapParams calldata params,
        ProgrammableBalanceDelta delta,
        bytes calldata hookData
    ) external returns (bytes4, int128);
}

interface IProgrammableV4PoolManagerV1 {
    function unlock(bytes calldata data) external returns (bytes memory result);
    function mint(address to, uint256 currencyId, uint256 amount) external;
    function burn(address from, uint256 currencyId, uint256 amount) external;
    function take(ProgrammableCurrency currency, address to, uint256 amount) external;
    function balanceOf(address owner, uint256 currencyId) external view returns (uint256);
}

interface IProgrammableFeeAdapterBindingV1 {
    function poolManager() external view returns (address);
    function platformFeeVault() external view returns (ProgrammableFeeVaultV1);
}

interface IProgrammableFeeAccrualContextV1 {
    function platformFeeAccrualContextHash() external view returns (bytes32);
}

/// @notice Typed external custom boundary for the isolated composition profile.
/// Module bytecode executes in its own storage context and can use arbitrary
/// Solidity or assembly without gaining the sealed hook's vault authority.
interface IProgrammableIsolatedAfterSwapModuleV1 {
    function afterSwapCustom(
        address sender,
        ProgrammablePoolKey calldata key,
        ProgrammableSwapParams calldata params,
        ProgrammableBalanceDelta delta,
        bytes calldata hookData
    ) external returns (bytes4 selector, int128 customDelta);
}

/// @title ProgrammableFeeVaultV1
/// @notice Isolated owner of all platform ERC-6909 claims. Arbitrary custom
/// hook code never owns, operates, approves, burns, or redirects these claims.
contract ProgrammableFeeVaultV1 {
    uint24 public constant PLATFORM_FEE_PPM = 1000;
    uint24 public constant FEE_DENOMINATOR_PPM = 1_000_000;
    address public constant PLATFORM_FEE_RECIPIENT = 0x4957f49620AFf3Adbbe8195a4f633E49cc93376c;
    uint160 public constant REQUIRED_ADAPTER_FLAGS = (1 << 6) | (1 << 2);
    uint160 public constant ALL_HOOK_MASK = (1 << 14) - 1;

    bytes32 private constant PLATFORM_FEE_ACCRUAL_CONTEXT_DOMAIN =
        keccak256("programmable.platform-fee-accrual-context.v1");

    address public immutable poolManager;
    address public bindingAuthority;
    address public authorizedAdapter;
    bytes32 public authorizedAdapterCodeHash;

    mapping(address currency => uint256 amount) public platformFeesAccrued;
    mapping(address currency => uint256 amount) public pendingPlatformFeeFunding;
    mapping(address currency => bytes32 contextHash) public pendingPlatformFeeContextHash;
    mapping(bytes32 poolId => mapping(address currency => uint256 scaledRemainder)) public platformFeeRemainderPpm;

    bool private bindingInProgress;
    bool private claimInProgress;
    bool private claimCallbackConsumed;
    bytes32 private activeClaimHash;

    error AdapterAlreadyBound(address adapter);
    error AdapterBindingStateChanged();
    error AdapterCodeHashChanged(bytes32 expected, bytes32 observed);
    error AdapterFeeAccrualContextPending(address currency, bytes32 contextHash);
    error AdapterFeeFundingPending(address currency, uint256 amount);
    error AdapterFeeFundingMismatch(address currency, uint256 expected, uint256 observed);
    error HookAddressPermissionMismatch(uint160 actual, uint160 required);
    error InvalidAdapterBinding(address adapter);
    error InvalidAddress();
    error InvalidPlatformFeeAccrualContext(bytes32 expected, bytes32 observed);
    error NoFeesToClaim(address currency);
    error ReentrantClaim();
    error ReentrantAdapterBinding();
    error UnauthorizedAdapter(address caller);
    error UnauthorizedBinding(address caller);
    error UnauthorizedClaim(address caller);
    error UnauthorizedPoolManager(address caller);
    error UnexpectedClaimCallback();
    error UnlockResponseNotEmpty();

    event AdapterBound(address indexed adapter);
    event PlatformFeeFundingRecorded(
        bytes32 indexed poolId,
        address indexed currency,
        bool exactInput,
        uint256 feeBasisAmount,
        uint256 platformFee,
        uint256 nextRemainderPpm
    );
    event PlatformFeeFundingConfirmed(address indexed currency, uint256 amount);
    event PlatformFeesClaimed(address indexed currency, address indexed treasury, uint256 amount);

    constructor(address poolManager_, address bindingAuthority_) {
        if (poolManager_ == address(0) || bindingAuthority_ == address(0)) {
            revert InvalidAddress();
        }
        poolManager = poolManager_;
        bindingAuthority = bindingAuthority_;
    }

    /// @notice One-time, self-sealing adapter binding performed by the exact
    /// atomic launch route after both vault and hook have been deployed.
    function bindAdapter(address adapter) external {
        if (msg.sender != bindingAuthority) revert UnauthorizedBinding(msg.sender);
        _beforeAdapterBinding();
        if (bindingInProgress) revert ReentrantAdapterBinding();
        if (authorizedAdapter != address(0)) revert AdapterAlreadyBound(authorizedAdapter);
        // The adapter getters below are external calls. Lock before validating
        // them and re-check the exact pre-bind state before sealing so a
        // selector-spoof adapter cannot create a transient alternate binding.
        bindingInProgress = true;
        bytes32 adapterCodeHash = adapter.codehash;
        uint160 flags = uint160(adapter) & ALL_HOOK_MASK;
        uint160 requiredFlags = requiredAdapterFlags();
        if (adapter == address(0) || adapter.code.length == 0 || flags != requiredFlags) {
            revert HookAddressPermissionMismatch(flags, requiredFlags);
        }
        try IProgrammableFeeAdapterBindingV1(adapter).poolManager() returns (address manager) {
            if (manager != poolManager) revert InvalidAdapterBinding(adapter);
        } catch {
            revert InvalidAdapterBinding(adapter);
        }
        try IProgrammableFeeAdapterBindingV1(adapter).platformFeeVault() returns (ProgrammableFeeVaultV1 vault) {
            if (address(vault) != address(this)) revert InvalidAdapterBinding(adapter);
        } catch {
            revert InvalidAdapterBinding(adapter);
        }
        try IProgrammableFeeAccrualContextV1(adapter).platformFeeAccrualContextHash() returns (bytes32 contextHash) {
            if (contextHash != bytes32(0)) revert InvalidAdapterBinding(adapter);
        } catch {
            revert InvalidAdapterBinding(adapter);
        }
        if (!bindingInProgress || authorizedAdapter != address(0) || bindingAuthority != msg.sender) {
            revert AdapterBindingStateChanged();
        }
        if (adapter.codehash != adapterCodeHash) {
            revert AdapterCodeHashChanged(adapterCodeHash, adapter.codehash);
        }
        authorizedAdapter = adapter;
        authorizedAdapterCodeHash = adapterCodeHash;
        bindingAuthority = address(0);
        bindingInProgress = false;
        emit AdapterBound(adapter);
    }

    /// @notice Exact address permission mask accepted by this vault version.
    /// V1 remains 0x0044; versioned descendants can strengthen the mask while
    /// retaining the proven accounting and claim implementation.
    function requiredAdapterFlags() public pure virtual returns (uint160) {
        return REQUIRED_ADAPTER_FLAGS;
    }

    function _beforeAdapterBinding() internal view virtual { }

    /// @notice Returns the exact context that the bound adapter must expose
    /// during the private mandatory fee phase for these immutable inputs.
    function platformFeeAccrualContextHash(
        bytes32 poolId,
        ProgrammableCurrency currency,
        uint256 feeBasisAmount,
        bool exactInput
    ) public view returns (bytes32) {
        return keccak256(
            abi.encode(
                PLATFORM_FEE_ACCRUAL_CONTEXT_DOMAIN,
                block.chainid,
                address(this),
                poolManager,
                authorizedAdapter,
                poolId,
                ProgrammableCurrency.unwrap(currency),
                feeBasisAmount,
                exactInput
            )
        );
    }

    /// @dev Starts one exact fee obligation only while the bound base module's
    /// private mandatory phase exposes the matching context. The context lock
    /// remains nonzero even when rounding produces a zero fee, so custom code
    /// cannot advance dust or create a second zero-value obligation.
    function recordPlatformFee(
        bytes32 poolId,
        ProgrammableCurrency currency,
        uint256 feeBasisAmount,
        bool exactInput,
        bytes32 accrualContextHash
    ) external returns (uint256 platformFee) {
        _onlyAdapter();
        address currencyAddress = ProgrammableCurrency.unwrap(currency);
        bytes32 pendingContext = pendingPlatformFeeContextHash[currencyAddress];
        if (pendingContext != bytes32(0)) {
            revert AdapterFeeAccrualContextPending(currencyAddress, pendingContext);
        }
        uint256 pending = pendingPlatformFeeFunding[currencyAddress];
        if (pending != 0) revert AdapterFeeFundingPending(currencyAddress, pending);

        bytes32 expectedContext = platformFeeAccrualContextHash(poolId, currency, feeBasisAmount, exactInput);
        if (accrualContextHash == bytes32(0) || accrualContextHash != expectedContext) {
            revert InvalidPlatformFeeAccrualContext(expectedContext, accrualContextHash);
        }
        _requireActiveAdapterAccrualContext(expectedContext);

        uint256 accounted = platformFeesAccrued[currencyAddress];
        uint256 observed = IProgrammableV4PoolManagerV1(poolManager).balanceOf(address(this), uint160(currencyAddress));
        if (observed < accounted) {
            revert AdapterFeeFundingMismatch(currencyAddress, accounted, observed);
        }

        uint256 nextRemainder;
        (platformFee, nextRemainder) = _computePlatformFee(poolId, currencyAddress, feeBasisAmount, exactInput);
        platformFeeRemainderPpm[poolId][currencyAddress] = nextRemainder;
        pendingPlatformFeeContextHash[currencyAddress] = expectedContext;
        pendingPlatformFeeFunding[currencyAddress] = platformFee;
        emit PlatformFeeFundingRecorded(poolId, currencyAddress, exactInput, feeBasisAmount, platformFee, nextRemainder);
    }

    function confirmPlatformFeeFunding(ProgrammableCurrency currency, uint256 amount, bytes32 accrualContextHash)
        external
    {
        _onlyAdapter();
        address currencyAddress = ProgrammableCurrency.unwrap(currency);
        bytes32 pendingContext = pendingPlatformFeeContextHash[currencyAddress];
        if (accrualContextHash == bytes32(0) || pendingContext == bytes32(0) || pendingContext != accrualContextHash) {
            revert InvalidPlatformFeeAccrualContext(pendingContext, accrualContextHash);
        }
        _requireActiveAdapterAccrualContext(pendingContext);
        uint256 pending = pendingPlatformFeeFunding[currencyAddress];
        if (pending != amount) {
            revert AdapterFeeFundingMismatch(currencyAddress, pending, amount);
        }
        uint256 nextAccounted = platformFeesAccrued[currencyAddress] + amount;
        uint256 observed = IProgrammableV4PoolManagerV1(poolManager).balanceOf(address(this), uint160(currencyAddress));
        if (observed < nextAccounted) {
            revert AdapterFeeFundingMismatch(currencyAddress, nextAccounted, observed);
        }
        pendingPlatformFeeContextHash[currencyAddress] = bytes32(0);
        pendingPlatformFeeFunding[currencyAddress] = 0;
        platformFeesAccrued[currencyAddress] = nextAccounted;
        emit PlatformFeeFundingConfirmed(currencyAddress, amount);
    }

    function claimPlatformFees(ProgrammableCurrency currency) external returns (uint256 amount) {
        if (msg.sender != PLATFORM_FEE_RECIPIENT) revert UnauthorizedClaim(msg.sender);
        if (claimInProgress) revert ReentrantClaim();

        address currencyAddress = ProgrammableCurrency.unwrap(currency);
        bytes32 pendingContext = pendingPlatformFeeContextHash[currencyAddress];
        if (pendingContext != bytes32(0)) {
            revert AdapterFeeAccrualContextPending(currencyAddress, pendingContext);
        }
        if (pendingPlatformFeeFunding[currencyAddress] != 0) {
            revert AdapterFeeFundingPending(currencyAddress, pendingPlatformFeeFunding[currencyAddress]);
        }
        amount = platformFeesAccrued[currencyAddress];
        if (amount == 0) revert NoFeesToClaim(currencyAddress);
        uint256 observed = IProgrammableV4PoolManagerV1(poolManager).balanceOf(address(this), uint160(currencyAddress));
        if (observed < amount) {
            revert AdapterFeeFundingMismatch(currencyAddress, amount, observed);
        }

        // Effects precede the only external call. Any failure, malformed
        // response, callback mismatch, or recipient reentry restores all state.
        platformFeesAccrued[currencyAddress] = 0;
        claimInProgress = true;
        claimCallbackConsumed = false;
        bytes memory callbackData = abi.encode(currency, amount);
        activeClaimHash = keccak256(callbackData);
        bytes memory result = IProgrammableV4PoolManagerV1(poolManager).unlock(callbackData);
        // The trusted PoolManager must have consumed the callback exactly once.
        // A return without callback cannot erase accounting without settlement.
        if (!claimCallbackConsumed || activeClaimHash != bytes32(0)) revert UnexpectedClaimCallback();
        if (result.length != 0) revert UnlockResponseNotEmpty();
        claimInProgress = false;
        claimCallbackConsumed = false;

        emit PlatformFeesClaimed(currencyAddress, PLATFORM_FEE_RECIPIENT, amount);
    }

    function unlockCallback(bytes calldata data) external returns (bytes memory) {
        if (msg.sender != poolManager) revert UnauthorizedPoolManager(msg.sender);
        if (!claimInProgress || claimCallbackConsumed) revert ReentrantClaim();
        if (keccak256(data) != activeClaimHash) revert UnexpectedClaimCallback();
        // Consume the one-shot callback before invoking PoolManager settlement.
        // The outer claim lock intentionally remains active until unlock fully
        // returns, so settlement callbacks cannot start a nested treasury claim.
        // Any downstream failure rolls this state change back atomically.
        claimCallbackConsumed = true;
        activeClaimHash = bytes32(0);
        (ProgrammableCurrency currency, uint256 amount) = abi.decode(data, (ProgrammableCurrency, uint256));
        uint256 currencyId = uint160(ProgrammableCurrency.unwrap(currency));
        IProgrammableV4PoolManagerV1(poolManager).burn(address(this), currencyId, amount);
        IProgrammableV4PoolManagerV1(poolManager).take(currency, PLATFORM_FEE_RECIPIENT, amount);
        return "";
    }

    function _onlyAdapter() private view {
        if (msg.sender != authorizedAdapter) revert UnauthorizedAdapter(msg.sender);
        bytes32 expectedCodeHash = authorizedAdapterCodeHash;
        bytes32 observedCodeHash = msg.sender.codehash;
        if (observedCodeHash != expectedCodeHash) {
            revert AdapterCodeHashChanged(expectedCodeHash, observedCodeHash);
        }
    }

    function _requireActiveAdapterAccrualContext(bytes32 expectedContext) private view {
        bytes32 observedContext = bytes32(0);
        try IProgrammableFeeAccrualContextV1(authorizedAdapter).platformFeeAccrualContextHash() returns (
            bytes32 contextHash
        ) {
            observedContext = contextHash;
        } catch {
            revert InvalidPlatformFeeAccrualContext(expectedContext, bytes32(0));
        }
        if (observedContext != expectedContext) {
            revert InvalidPlatformFeeAccrualContext(expectedContext, observedContext);
        }
    }

    function _computePlatformFee(bytes32 poolId, address currencyAddress, uint256 feeBasisAmount, bool exactInput)
        private
        view
        returns (uint256 platformFee, uint256 nextRemainder)
    {
        uint256 remainder = platformFeeRemainderPpm[poolId][currencyAddress];
        uint256 scaledPoolAmount = feeBasisAmount * PLATFORM_FEE_PPM;
        if (exactInput) {
            // The unspecified output amount is already the gross qualifying
            // amount. Carry one per-pool/currency remainder so splitting a
            // trade cannot change the cumulative 0.10% charge.
            uint256 scaledFee = scaledPoolAmount + remainder;
            return (scaledFee / FEE_DENOMINATOR_PPM, scaledFee % FEE_DENOMINATOR_PPM);
        }

        // The unspecified input amount excludes the hook fee. Solve the
        // integer fixed point with its minimum valid integer solution.
        uint256 scaledNetAmount = scaledPoolAmount + remainder;
        uint256 feeDivisor = FEE_DENOMINATOR_PPM - PLATFORM_FEE_PPM;
        platformFee =
            scaledNetAmount < FEE_DENOMINATOR_PPM ? 0 : (scaledNetAmount - FEE_DENOMINATOR_PPM) / feeDivisor + 1;
        uint256 grossAmount = feeBasisAmount + platformFee;
        nextRemainder = (remainder + grossAmount * PLATFORM_FEE_PPM) % FEE_DENOMINATOR_PPM;
    }
}

/// @title ProgrammableAdditiveFeeModuleV1
/// @notice Single-hook execution adapter that composes arbitrary custom
/// afterSwap logic with an independently owned, fixed 0.10% platform claim.
abstract contract ProgrammableAdditiveFeeModuleV1 is IProgrammableV4HookV1 {
    uint24 public constant PLATFORM_FEE_PPM = 1000;
    uint24 public constant FEE_DENOMINATOR_PPM = 1_000_000;
    address public constant PLATFORM_FEE_RECIPIENT = 0x4957f49620AFf3Adbbe8195a4f633E49cc93376c;
    uint160 public constant ALL_HOOK_MASK = (1 << 14) - 1;
    uint160 public constant AFTER_SWAP_FLAG = 1 << 6;
    uint160 public constant AFTER_SWAP_RETURNS_DELTA_FLAG = 1 << 2;
    uint160 public constant REQUIRED_HOOK_FLAGS = AFTER_SWAP_FLAG | AFTER_SWAP_RETURNS_DELTA_FLAG;

    address public immutable poolManager;
    ProgrammableFeeVaultV1 public immutable platformFeeVault;

    bytes32 private activePlatformFeeAccrualContextHash;

    error AfterSwapDeltaOverflow(int128 customDelta, int128 platformDelta);
    error HookAddressPermissionMismatch(uint160 actual, uint160 expected);
    error InvalidPlatformFeeVault();
    error InvalidPoolManager();
    error ReentrantPlatformFeeAccrual();
    error UnexpectedPoolHook(address actual);
    error UnexpectedUnlockCallback();
    error UnexpectedUnspecifiedDelta(int128 amount);
    error UnauthorizedPoolManager(address caller);

    event PlatformFeeAccrued(
        bytes32 indexed poolId,
        address indexed currency,
        address indexed swapSender,
        bool exactInput,
        uint256 grossQualifyingAmount,
        uint256 platformFee,
        address feeVault
    );

    constructor(address poolManager_, ProgrammableFeeVaultV1 platformFeeVault_) {
        if (poolManager_ == address(0)) revert InvalidPoolManager();
        if (
            address(platformFeeVault_) == address(0) || platformFeeVault_.poolManager() != poolManager_
                || platformFeeVault_.PLATFORM_FEE_RECIPIENT() != PLATFORM_FEE_RECIPIENT
        ) revert InvalidPlatformFeeVault();
        uint160 flags = uint160(address(this)) & ALL_HOOK_MASK;
        if (flags != REQUIRED_HOOK_FLAGS) {
            revert HookAddressPermissionMismatch(flags, REQUIRED_HOOK_FLAGS);
        }
        poolManager = poolManager_;
        platformFeeVault = platformFeeVault_;
    }

    function afterSwap(
        address sender,
        ProgrammablePoolKey calldata key,
        ProgrammableSwapParams calldata params,
        ProgrammableBalanceDelta delta,
        bytes calldata hookData
    ) external returns (bytes4, int128) {
        if (msg.sender != poolManager) revert UnauthorizedPoolManager(msg.sender);
        if (key.hooks != address(this)) revert UnexpectedPoolHook(key.hooks);

        int128 platformDelta = _accrueProgrammablePlatformFee(sender, key, params, delta);
        // The mandatory platform path always executes before optional custom
        // behavior. A later revert rolls the entire callback back atomically.
        int128 customDelta = _afterSwapCustom(sender, key, params, delta, hookData);
        return (IProgrammableV4HookV1.afterSwap.selector, _checkedAddAfterSwapDelta(customDelta, platformDelta));
    }

    function _afterSwapCustom(
        address,
        ProgrammablePoolKey calldata,
        ProgrammableSwapParams calldata,
        ProgrammableBalanceDelta,
        bytes calldata
    ) internal virtual returns (int128) {
        return 0;
    }

    /// @notice Exact mandatory-phase capability observed by the isolated vault.
    /// This non-virtual getter is zero before optional custom code executes.
    function platformFeeAccrualContextHash() public view returns (bytes32) {
        return activePlatformFeeAccrualContextHash;
    }

    function _accrueProgrammablePlatformFee(
        address sender,
        ProgrammablePoolKey calldata key,
        ProgrammableSwapParams calldata params,
        ProgrammableBalanceDelta delta
    ) private returns (int128 platformDelta) {
        if (activePlatformFeeAccrualContextHash != bytes32(0)) {
            revert ReentrantPlatformFeeAccrual();
        }
        bytes32 poolId = keccak256(abi.encode(key));
        bool exactInput = params.amountSpecified < 0;
        bool unspecifiedIsCurrency0 = exactInput != params.zeroForOne;
        int128 unspecifiedDelta = unspecifiedIsCurrency0 ? _amount0(delta) : _amount1(delta);
        ProgrammableCurrency feeCurrency = unspecifiedIsCurrency0 ? key.currency0 : key.currency1;

        uint256 feeBasisAmount;
        if (exactInput) {
            if (unspecifiedDelta < 0) revert UnexpectedUnspecifiedDelta(unspecifiedDelta);
            feeBasisAmount = uint128(unspecifiedDelta);
        } else {
            if (unspecifiedDelta > 0) revert UnexpectedUnspecifiedDelta(unspecifiedDelta);
            feeBasisAmount = _absolute(unspecifiedDelta);
        }
        bytes32 accrualContextHash =
            platformFeeVault.platformFeeAccrualContextHash(poolId, feeCurrency, feeBasisAmount, exactInput);
        if (accrualContextHash == bytes32(0)) revert ReentrantPlatformFeeAccrual();
        activePlatformFeeAccrualContextHash = accrualContextHash;
        uint256 platformFee =
            platformFeeVault.recordPlatformFee(poolId, feeCurrency, feeBasisAmount, exactInput, accrualContextHash);
        if (platformFee > uint128(type(int128).max)) {
            revert UnexpectedUnspecifiedDelta(unspecifiedDelta);
        }
        if (platformFee > 0) {
            IProgrammableV4PoolManagerV1(poolManager)
                .mint(address(platformFeeVault), uint160(ProgrammableCurrency.unwrap(feeCurrency)), platformFee);
        }
        platformFeeVault.confirmPlatformFeeFunding(feeCurrency, platformFee, accrualContextHash);
        activePlatformFeeAccrualContextHash = bytes32(0);

        uint256 grossQualifyingAmount = exactInput ? feeBasisAmount : feeBasisAmount + platformFee;
        emit PlatformFeeAccrued(
            poolId,
            ProgrammableCurrency.unwrap(feeCurrency),
            sender,
            exactInput,
            grossQualifyingAmount,
            platformFee,
            address(platformFeeVault)
        );
        return int128(uint128(platformFee));
    }

    function _checkedAddAfterSwapDelta(int128 customDelta, int128 platformDelta)
        internal
        pure
        returns (int128 combinedDelta)
    {
        int256 combined = int256(customDelta) + int256(platformDelta);
        if (combined < type(int128).min || combined > type(int128).max) {
            revert AfterSwapDeltaOverflow(customDelta, platformDelta);
        }
        return int128(combined);
    }

    function unlockCallback(bytes calldata data) external returns (bytes memory) {
        if (msg.sender != poolManager) revert UnauthorizedPoolManager(msg.sender);
        return _unlockCallbackCustom(data);
    }

    function _unlockCallbackCustom(bytes calldata) internal virtual returns (bytes memory) {
        revert UnexpectedUnlockCallback();
    }

    function platformFeesAccrued(address currency) external view returns (uint256) {
        return platformFeeVault.platformFeesAccrued(currency);
    }

    function platformFeeRemainderPpm(bytes32 poolId, address currency) external view returns (uint256) {
        return platformFeeVault.platformFeeRemainderPpm(poolId, currency);
    }

    function _amount0(ProgrammableBalanceDelta delta) private pure returns (int128) {
        return int128(ProgrammableBalanceDelta.unwrap(delta) >> 128);
    }

    function _amount1(ProgrammableBalanceDelta delta) private pure returns (int128) {
        return int128(ProgrammableBalanceDelta.unwrap(delta));
    }

    function _absolute(int128 value) private pure returns (uint256) {
        if (value >= 0) return uint128(value);
        return uint128(-(value + 1)) + 1;
    }
}

/// @title ProgrammableAdditiveFeeHookV1
/// @notice Standalone zero-custom-fee adapter with exact 0x0044 permissions.
contract ProgrammableAdditiveFeeHookV1 is ProgrammableAdditiveFeeModuleV1 {
    constructor(address poolManager_, ProgrammableFeeVaultV1 platformFeeVault_)
        ProgrammableAdditiveFeeModuleV1(poolManager_, platformFeeVault_)
    {
        uint160 flags = uint160(address(this)) & ALL_HOOK_MASK;
        if (flags != REQUIRED_HOOK_FLAGS) {
            revert HookAddressPermissionMismatch(flags, REQUIRED_HOOK_FLAGS);
        }
    }

    function getHookPermissions() external pure returns (ProgrammableHookPermissions memory permissions) {
        permissions.afterSwap = true;
        permissions.afterSwapReturnDelta = true;
    }
}

/// @title ProgrammableIsolatedAfterSwapFeeHookV1
/// @notice Sealed platform-fee adapter for custom logic that requires
/// arbitrary raw-storage writes or delegatecall. Ordinary compiler-laid-out
/// state remains eligible for same-address composition after exact review. The
/// immutable external module runs with separate storage and returns only one
/// bounded unspecified-currency delta.
/// The sealed hook, never the custom module, settles that delta under the hook
/// address that PoolManager accounts when it processes the callback return.
contract ProgrammableIsolatedAfterSwapFeeHookV1 is ProgrammableAdditiveFeeModuleV1 {
    IProgrammableIsolatedAfterSwapModuleV1 public immutable customModule;
    address public immutable customDeltaAccount;
    uint128 public immutable maximumCustomDeltaAbsolute;

    error CustomDeltaExceedsBound(int128 customDelta, uint128 maximumAbsolute);
    error InvalidCustomDeltaAccount();
    error InvalidCustomDeltaBound(uint128 maximumAbsolute);
    error InvalidCustomModule(address module);
    error UnexpectedCustomModuleSelector(bytes4 actual);

    event IsolatedCustomDeltaSettled(
        address indexed module, address indexed account, address indexed currency, int128 customDelta
    );

    constructor(
        address poolManager_,
        ProgrammableFeeVaultV1 platformFeeVault_,
        IProgrammableIsolatedAfterSwapModuleV1 customModule_,
        address customDeltaAccount_,
        uint128 maximumCustomDeltaAbsolute_
    ) ProgrammableAdditiveFeeModuleV1(poolManager_, platformFeeVault_) {
        address module = address(customModule_);
        if (
            module == address(0) || module == poolManager_ || module == address(platformFeeVault_)
                || module.code.length == 0
        ) revert InvalidCustomModule(module);
        if (
            customDeltaAccount_ == address(0) || customDeltaAccount_ == poolManager_
                || customDeltaAccount_ == address(platformFeeVault_) || customDeltaAccount_ == address(this)
        ) revert InvalidCustomDeltaAccount();
        if (maximumCustomDeltaAbsolute_ > uint128(type(int128).max)) {
            revert InvalidCustomDeltaBound(maximumCustomDeltaAbsolute_);
        }
        uint160 flags = uint160(address(this)) & ALL_HOOK_MASK;
        if (flags != REQUIRED_HOOK_FLAGS) {
            revert HookAddressPermissionMismatch(flags, REQUIRED_HOOK_FLAGS);
        }
        customModule = customModule_;
        customDeltaAccount = customDeltaAccount_;
        maximumCustomDeltaAbsolute = maximumCustomDeltaAbsolute_;
    }

    function getHookPermissions() external pure returns (ProgrammableHookPermissions memory permissions) {
        permissions.afterSwap = true;
        permissions.afterSwapReturnDelta = true;
    }

    function _afterSwapCustom(
        address sender,
        ProgrammablePoolKey calldata key,
        ProgrammableSwapParams calldata params,
        ProgrammableBalanceDelta delta,
        bytes calldata hookData
    ) internal override returns (int128 customDelta) {
        bytes4 selector;
        (selector, customDelta) = customModule.afterSwapCustom(sender, key, params, delta, hookData);
        if (selector != IProgrammableIsolatedAfterSwapModuleV1.afterSwapCustom.selector) {
            revert UnexpectedCustomModuleSelector(selector);
        }

        uint256 magnitude = customDelta >= 0 ? uint128(customDelta) : uint128(-(customDelta + 1)) + 1;
        if (magnitude > maximumCustomDeltaAbsolute) {
            revert CustomDeltaExceedsBound(customDelta, maximumCustomDeltaAbsolute);
        }
        if (magnitude == 0) return 0;

        bool exactInput = params.amountSpecified < 0;
        bool unspecifiedIsCurrency0 = exactInput != params.zeroForOne;
        ProgrammableCurrency currency = unspecifiedIsCurrency0 ? key.currency0 : key.currency1;
        uint256 currencyId = uint160(ProgrammableCurrency.unwrap(currency));
        if (customDelta > 0) {
            IProgrammableV4PoolManagerV1(poolManager).mint(customDeltaAccount, currencyId, magnitude);
        } else {
            // Negative custom deltas are explicit rebates. They succeed only
            // when the immutable account pre-authorized this sealed hook to
            // burn enough PoolManager claims; otherwise the whole swap reverts.
            IProgrammableV4PoolManagerV1(poolManager).burn(customDeltaAccount, currencyId, magnitude);
        }
        emit IsolatedCustomDeltaSettled(
            address(customModule), customDeltaAccount, ProgrammableCurrency.unwrap(currency), customDelta
        );
    }
}

src/ProgrammableAdditiveFeeHookV2.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {
    IProgrammableIsolatedAfterSwapModuleV1,
    IProgrammableV4HookV1,
    IProgrammableV4PoolManagerV1,
    ProgrammableBalanceDelta,
    ProgrammableCurrency,
    ProgrammableHookPermissions,
    ProgrammablePoolKey,
    ProgrammableSwapParams
} from "./ProgrammableAdditiveFeeHookV1.sol";
import {
    PROGRAMMABLE_CANONICAL_GRAPH_DEPLOYER_RUNTIME_CODE_HASH_V2,
    PROGRAMMABLE_CANONICAL_GRAPH_DEPLOYER_V2,
    PROGRAMMABLE_CANONICAL_POOL_MANAGER_RUNTIME_CODE_HASH_V2,
    PROGRAMMABLE_CANONICAL_POOL_MANAGER_V2,
    ProgrammableFeeVaultV2Core
} from "./ProgrammableFeeVaultV2.sol";

uint16 constant PROGRAMMABLE_FEE_POLICY_VERSION_V2 = 2;
uint256 constant PROGRAMMABLE_FEE_POLICY_CHAIN_ID_V2 = 1;
uint24 constant PROGRAMMABLE_FEE_POLICY_RATE_PPM_V2 = 1000;
uint24 constant PROGRAMMABLE_FEE_POLICY_DENOMINATOR_PPM_V2 = 1_000_000;
address constant PROGRAMMABLE_FEE_POLICY_RECIPIENT_V2 = 0x4957f49620AFf3Adbbe8195a4f633E49cc93376c;
uint160 constant PROGRAMMABLE_FEE_POLICY_REQUIRED_HOOK_FLAGS_V2 = (1 << 13) | (1 << 6) | (1 << 2);

bytes32 constant PROGRAMMABLE_FEE_POLICY_DOMAIN_V2 = keccak256("programmable.custom-fee-policy.v2");
bytes32 constant PROGRAMMABLE_FEE_BASIS_V2 =
    keccak256("programmable.fee-basis.v2.gross-unspecified-pool-currency-amount");
bytes32 constant PROGRAMMABLE_FEE_ASSET_MODE_V2 =
    keccak256("programmable.fee-asset-mode.v2.unspecified-pool-currency-per-swap");
bytes32 constant PROGRAMMABLE_ZERO_CUSTOM_PROFILE_V2 = keccak256("programmable.fee-hook-profile.v2.zero-custom");
bytes32 constant PROGRAMMABLE_ISOLATED_AFTER_SWAP_PROFILE_V2 =
    keccak256("programmable.fee-hook-profile.v2.isolated-after-swap-zero-delta-opcode-safe");
bytes32 constant PROGRAMMABLE_COMPILER_SETTINGS_HASH_V2 =
    keccak256("solc-0.8.26|evm-cancun|optimizer-true|runs-1000|viaIR-false|bytecodeHash-ipfs|cborMetadata-true");
bytes32 constant PROGRAMMABLE_DEPLOYMENT_PROFILE_DOMAIN_V2 = keccak256("programmable.fee-deployment-profile.v2");
bytes32 constant PROGRAMMABLE_COMPOSITION_DOMAIN_V2 = keccak256("programmable.fee-composition.v2");

bytes32 constant PROGRAMMABLE_FEE_VAULT_V2_RUNTIME_CODE_HASH =
    0xf9638e198b83c2ada6cfb34d108d2b0a8356fb4679847bd1d5f3127dee1f24d5;
bytes32 constant PROGRAMMABLE_LAUNCH_TOKEN_V2_RUNTIME_CODE_HASH =
    0xf98eb029ee9c1face4b56fafd83612be8b813bf15a402a959ac107de8b203eef;

function programmableFeePolicyIdV2(bytes32 profile) pure returns (bytes32) {
    return keccak256(
        abi.encode(
            PROGRAMMABLE_FEE_POLICY_DOMAIN_V2,
            PROGRAMMABLE_FEE_POLICY_VERSION_V2,
            PROGRAMMABLE_FEE_POLICY_CHAIN_ID_V2,
            profile,
            PROGRAMMABLE_FEE_BASIS_V2,
            PROGRAMMABLE_FEE_ASSET_MODE_V2,
            PROGRAMMABLE_FEE_POLICY_RATE_PPM_V2,
            PROGRAMMABLE_FEE_POLICY_DENOMINATOR_PPM_V2,
            PROGRAMMABLE_FEE_POLICY_RECIPIENT_V2,
            PROGRAMMABLE_FEE_POLICY_REQUIRED_HOOK_FLAGS_V2
        )
    );
}

function programmableDeploymentProfileHashV2(
    bytes32 profile,
    bytes32 hookRuntimeCodeHash,
    bytes32 vaultRuntimeCodeHash,
    bytes32 tokenRuntimeCodeHash,
    bytes32 customModuleRuntimeCodeHash
) pure returns (bytes32) {
    return keccak256(
        abi.encode(
            PROGRAMMABLE_DEPLOYMENT_PROFILE_DOMAIN_V2,
            programmableFeePolicyIdV2(profile),
            PROGRAMMABLE_COMPILER_SETTINGS_HASH_V2,
            PROGRAMMABLE_CANONICAL_POOL_MANAGER_V2,
            PROGRAMMABLE_CANONICAL_POOL_MANAGER_RUNTIME_CODE_HASH_V2,
            PROGRAMMABLE_CANONICAL_GRAPH_DEPLOYER_V2,
            PROGRAMMABLE_CANONICAL_GRAPH_DEPLOYER_RUNTIME_CODE_HASH_V2,
            hookRuntimeCodeHash,
            vaultRuntimeCodeHash,
            tokenRuntimeCodeHash,
            customModuleRuntimeCodeHash,
            uint128(0)
        )
    );
}

struct ProgrammableCompositionV2 {
    bytes32 deploymentProfileHash;
    address hook;
    bytes32 hookRuntimeCodeHash;
    address vault;
    bytes32 vaultRuntimeCodeHash;
    address initializer;
    bytes32 initializerRuntimeCodeHash;
    bytes32 poolId;
    uint160 initialSqrtPriceX96;
    address token;
    bytes32 tokenRuntimeCodeHash;
    address customModule;
    bytes32 customModuleRuntimeCodeHash;
    address customDeltaAccount;
    uint128 maximumCustomDeltaAbsolute;
}

function programmableCompositionHashV2(ProgrammableCompositionV2 memory composition) pure returns (bytes32) {
    bytes32 platformComposition = keccak256(
        abi.encode(
            composition.hook,
            composition.hookRuntimeCodeHash,
            composition.vault,
            composition.vaultRuntimeCodeHash,
            composition.initializer,
            composition.initializerRuntimeCodeHash
        )
    );
    bytes32 poolComposition = keccak256(
        abi.encode(
            composition.poolId, composition.initialSqrtPriceX96, composition.token, composition.tokenRuntimeCodeHash
        )
    );
    bytes32 customComposition = keccak256(
        abi.encode(
            composition.customModule,
            composition.customModuleRuntimeCodeHash,
            composition.customDeltaAccount,
            composition.maximumCustomDeltaAbsolute
        )
    );
    return keccak256(
        abi.encode(
            PROGRAMMABLE_COMPOSITION_DOMAIN_V2,
            composition.deploymentProfileHash,
            platformComposition,
            poolComposition,
            customComposition
        )
    );
}

function programmableModuleCodeIsSafeV2(bytes memory runtimeCode) pure returns (bool) {
    uint256 cursor;
    while (cursor < runtimeCode.length) {
        uint8 opcode = uint8(runtimeCode[cursor]);
        if (opcode == 0xf2 || opcode == 0xf4 || opcode == 0xff) return false;
        unchecked {
            if (opcode >= 0x60 && opcode <= 0x7f) cursor += uint256(opcode) - 0x5f + 1;
            else ++cursor;
        }
    }
    return true;
}

interface IProgrammableFeePolicyProfileV2 {
    function feePolicyVersion() external view returns (uint16);
    function feePolicyChainId() external view returns (uint256);
    function feePolicyId() external view returns (bytes32);
    function feePolicyProfile() external view returns (bytes32);
    function feePolicyBasis() external view returns (bytes32);
    function feePolicyAssetMode() external view returns (bytes32);
    function feePolicyRatePpm() external view returns (uint24);
    function feePolicyDenominatorPpm() external view returns (uint24);
    function feePolicyRecipient() external view returns (address);
    function feePolicyRequiredHookFlags() external view returns (uint160);
    function feePolicyCustomModule() external view returns (address);
    function feePolicyCustomModuleRuntimeCodeHash() external view returns (bytes32);
    function feePolicyCustomDeltaAccount() external view returns (address);
    function feePolicyMaximumCustomDeltaAbsolute() external view returns (uint128);
}

interface IProgrammableV4HookV2 is IProgrammableV4HookV1 {
    function beforeInitialize(address sender, ProgrammablePoolKey calldata key, uint160 sqrtPriceX96)
        external
        returns (bytes4);
}

abstract contract ProgrammableAdditiveFeeHookV2Core is IProgrammableV4HookV2, IProgrammableFeePolicyProfileV2 {
    uint24 public constant PLATFORM_FEE_PPM = PROGRAMMABLE_FEE_POLICY_RATE_PPM_V2;
    uint24 public constant FEE_DENOMINATOR_PPM = PROGRAMMABLE_FEE_POLICY_DENOMINATOR_PPM_V2;
    address public constant PLATFORM_FEE_RECIPIENT = PROGRAMMABLE_FEE_POLICY_RECIPIENT_V2;
    uint160 public constant ALL_HOOK_MASK = (1 << 14) - 1;
    uint160 public constant BEFORE_INITIALIZE_FLAG = 1 << 13;
    uint160 public constant AFTER_SWAP_FLAG = 1 << 6;
    uint160 public constant AFTER_SWAP_RETURNS_DELTA_FLAG = 1 << 2;
    uint160 public constant REQUIRED_HOOK_FLAGS = PROGRAMMABLE_FEE_POLICY_REQUIRED_HOOK_FLAGS_V2;

    address public poolManager;
    address public graphDeployer;
    ProgrammableFeeVaultV2Core public platformFeeVault;
    bool public poolBindingComplete;
    bool public poolInitialized;
    address public authorizedInitializer;
    bytes32 public authorizedInitializerRuntimeCodeHash;
    bytes32 public boundPoolId;
    uint160 public boundInitialSqrtPriceX96;
    address public boundToken;
    bytes32 public boundHookRuntimeCodeHash;
    bytes32 public boundVaultRuntimeCodeHash;
    bytes32 public boundTokenRuntimeCodeHash;
    bytes32 public deploymentProfileHash;
    bytes32 public compositionHash;
    bytes32 private activePlatformFeeAccrualContextHash;

    error AfterSwapDeltaOverflow(int128 customDelta, int128 platformDelta);
    error AlreadyPoolBound(bytes32 poolId);
    error CompositionDrift(bytes32 expected, bytes32 actual);
    error HookAddressPermissionMismatch(uint160 actual, uint160 expected);
    error InvalidAddress();
    error InvalidCustomModule(address module);
    error InvalidCustomModuleOpcode(address module);
    error InvalidPlatformFeeVault();
    error PoolAlreadyInitialized(bytes32 poolId);
    error PoolBindingIncomplete();
    error ReentrantPlatformFeeAccrual();
    error RuntimeCodeHashMismatch(address target, bytes32 expected, bytes32 actual);
    error UnexpectedInitialSqrtPrice(uint160 actual, uint160 expected);
    error UnexpectedPool(bytes32 actual, bytes32 expected);
    error UnexpectedPoolHook(address actual);
    error UnexpectedUnlockCallback();
    error UnexpectedUnspecifiedDelta(int128 amount);
    error UnauthorizedGraphDeployer(address caller);
    error UnauthorizedInitializer(address caller);
    error UnauthorizedPoolManager(address caller);
    error UnsupportedFeePolicyChain(uint256 actual, uint256 required);

    event PoolBindingSealed(
        bytes32 indexed poolId,
        address indexed initializer,
        bytes32 indexed deploymentProfileHash,
        bytes32 compositionHash,
        bytes32 hookRuntimeCodeHash,
        bytes32 vaultRuntimeCodeHash,
        bytes32 initializerRuntimeCodeHash,
        uint160 initialSqrtPriceX96
    );
    event PoolInitializationAuthorized(bytes32 indexed poolId, address indexed initializer, uint160 sqrtPriceX96);
    event PlatformFeeAccrued(
        bytes32 indexed poolId,
        address indexed currency,
        address indexed swapSender,
        bool exactInput,
        uint256 grossQualifyingAmount,
        uint256 platformFee,
        address feeVault
    );

    constructor(address poolManager_, address graphDeployer_, ProgrammableFeeVaultV2Core platformFeeVault_) {
        if (poolManager_ == address(0) || graphDeployer_ == address(0) || address(platformFeeVault_) == address(0)) {
            revert InvalidAddress();
        }
        uint160 flags = uint160(address(this)) & ALL_HOOK_MASK;
        if (flags != REQUIRED_HOOK_FLAGS) revert HookAddressPermissionMismatch(flags, REQUIRED_HOOK_FLAGS);
        poolManager = poolManager_;
        graphDeployer = graphDeployer_;
        platformFeeVault = platformFeeVault_;
    }

    function bindPool(ProgrammablePoolKey calldata key, address initializer, uint160 initialSqrtPriceX96) external {
        if (msg.sender != graphDeployer) revert UnauthorizedGraphDeployer(msg.sender);
        _requireEnvironment();
        if (poolBindingComplete) revert AlreadyPoolBound(boundPoolId);
        if (initializer == address(0) || initializer.code.length == 0 || initialSqrtPriceX96 == 0) {
            revert InvalidAddress();
        }
        if (key.hooks != address(this)) revert UnexpectedPoolHook(key.hooks);
        if (
            ProgrammableCurrency.unwrap(key.currency0) != address(0)
                || ProgrammableCurrency.unwrap(key.currency1) == address(0)
        ) revert UnexpectedPool(keccak256(abi.encode(key)), bytes32(0));

        bytes32 hookRuntime = address(this).codehash;
        bytes32 vaultRuntime = address(platformFeeVault).codehash;
        address token = ProgrammableCurrency.unwrap(key.currency1);
        bytes32 tokenRuntime = token.codehash;
        bytes32 expectedTokenRuntime = _expectedTokenRuntimeCodeHash();
        if (tokenRuntime != expectedTokenRuntime) {
            revert RuntimeCodeHashMismatch(token, expectedTokenRuntime, tokenRuntime);
        }
        bytes32 expectedVaultRuntime = _expectedVaultRuntimeCodeHash();
        if (vaultRuntime != expectedVaultRuntime) {
            revert RuntimeCodeHashMismatch(address(platformFeeVault), expectedVaultRuntime, vaultRuntime);
        }
        if (
            platformFeeVault.bindingAuthority() != address(0) || platformFeeVault.authorizedAdapter() != address(this)
                || platformFeeVault.authorizedAdapterCodeHash() != hookRuntime
                || platformFeeVault.poolManager() != poolManager
                || platformFeeVault.requiredAdapterFlags() != REQUIRED_HOOK_FLAGS
        ) revert InvalidPlatformFeeVault();
        _validateCustomModule();

        bytes32 poolId = keccak256(abi.encode(key));
        bytes32 profileHash = programmableDeploymentProfileHashV2(
            _profileKind(), hookRuntime, vaultRuntime, tokenRuntime, _customModuleRuntimeCodeHash()
        );

        authorizedInitializer = initializer;
        authorizedInitializerRuntimeCodeHash = initializer.codehash;
        boundPoolId = poolId;
        boundInitialSqrtPriceX96 = initialSqrtPriceX96;
        boundToken = token;
        boundHookRuntimeCodeHash = hookRuntime;
        boundVaultRuntimeCodeHash = vaultRuntime;
        boundTokenRuntimeCodeHash = tokenRuntime;
        deploymentProfileHash = profileHash;
        poolBindingComplete = true;
        compositionHash = _currentCompositionHash();
        _emitPoolBindingSealed();
    }

    function _emitPoolBindingSealed() private {
        emit PoolBindingSealed(
            boundPoolId,
            authorizedInitializer,
            deploymentProfileHash,
            compositionHash,
            boundHookRuntimeCodeHash,
            boundVaultRuntimeCodeHash,
            authorizedInitializerRuntimeCodeHash,
            boundInitialSqrtPriceX96
        );
    }

    function beforeInitialize(address sender, ProgrammablePoolKey calldata key, uint160 sqrtPriceX96)
        external
        returns (bytes4)
    {
        if (msg.sender != poolManager) revert UnauthorizedPoolManager(msg.sender);
        if (!poolBindingComplete) revert PoolBindingIncomplete();
        if (poolInitialized) revert PoolAlreadyInitialized(boundPoolId);
        if (sender != authorizedInitializer) revert UnauthorizedInitializer(sender);
        bytes32 actualPoolId = keccak256(abi.encode(key));
        if (actualPoolId != boundPoolId) revert UnexpectedPool(actualPoolId, boundPoolId);
        if (sqrtPriceX96 != boundInitialSqrtPriceX96) {
            revert UnexpectedInitialSqrtPrice(sqrtPriceX96, boundInitialSqrtPriceX96);
        }
        _requireBoundComposition();
        poolInitialized = true;
        emit PoolInitializationAuthorized(actualPoolId, sender, sqrtPriceX96);
        return IProgrammableV4HookV2.beforeInitialize.selector;
    }

    function afterSwap(
        address sender,
        ProgrammablePoolKey calldata key,
        ProgrammableSwapParams calldata params,
        ProgrammableBalanceDelta delta,
        bytes calldata hookData
    ) external returns (bytes4, int128) {
        if (msg.sender != poolManager) revert UnauthorizedPoolManager(msg.sender);
        if (!poolInitialized) revert PoolBindingIncomplete();
        bytes32 actualPoolId = keccak256(abi.encode(key));
        if (actualPoolId != boundPoolId) revert UnexpectedPool(actualPoolId, boundPoolId);
        if (key.hooks != address(this)) revert UnexpectedPoolHook(key.hooks);
        _requireBoundComposition();
        int128 platformDelta = _accrueProgrammablePlatformFee(sender, key, params, delta);
        int128 customDelta = _afterSwapCustom(sender, key, params, delta, hookData);
        return (IProgrammableV4HookV1.afterSwap.selector, _checkedAddAfterSwapDelta(customDelta, platformDelta));
    }

    function getHookPermissions() external pure returns (ProgrammableHookPermissions memory permissions) {
        permissions.beforeInitialize = true;
        permissions.afterSwap = true;
        permissions.afterSwapReturnDelta = true;
    }

    function platformFeeAccrualContextHash() public view returns (bytes32) {
        return activePlatformFeeAccrualContextHash;
    }

    function platformFeesAccrued(address currency) external view returns (uint256) {
        return platformFeeVault.platformFeesAccrued(currency);
    }

    function platformFeeRemainderPpm(bytes32 poolId, address currency) external view returns (uint256) {
        return platformFeeVault.platformFeeRemainderPpm(poolId, currency);
    }

    function feePolicyVersion() external pure returns (uint16) {
        return PROGRAMMABLE_FEE_POLICY_VERSION_V2;
    }

    function feePolicyChainId() external pure returns (uint256) {
        return PROGRAMMABLE_FEE_POLICY_CHAIN_ID_V2;
    }

    function feePolicyId() external view returns (bytes32) {
        return programmableFeePolicyIdV2(_profileKind());
    }

    function feePolicyProfile() external view returns (bytes32) {
        return _profileKind();
    }

    function feePolicyBasis() external pure returns (bytes32) {
        return PROGRAMMABLE_FEE_BASIS_V2;
    }

    function feePolicyAssetMode() external pure returns (bytes32) {
        return PROGRAMMABLE_FEE_ASSET_MODE_V2;
    }

    function feePolicyRatePpm() external pure returns (uint24) {
        return PROGRAMMABLE_FEE_POLICY_RATE_PPM_V2;
    }

    function feePolicyDenominatorPpm() external pure returns (uint24) {
        return PROGRAMMABLE_FEE_POLICY_DENOMINATOR_PPM_V2;
    }

    function feePolicyRecipient() external pure returns (address) {
        return PROGRAMMABLE_FEE_POLICY_RECIPIENT_V2;
    }

    function feePolicyRequiredHookFlags() external pure returns (uint160) {
        return PROGRAMMABLE_FEE_POLICY_REQUIRED_HOOK_FLAGS_V2;
    }

    function feePolicyMaximumCustomDeltaAbsolute() external pure returns (uint128) {
        return 0;
    }

    function feePolicyCustomDeltaAccount() external pure returns (address) {
        return address(0);
    }

    function feePolicyCompilerSettingsHash() external pure returns (bytes32) {
        return PROGRAMMABLE_COMPILER_SETTINGS_HASH_V2;
    }

    function feePolicyDeploymentProfileDomain() external pure returns (bytes32) {
        return PROGRAMMABLE_DEPLOYMENT_PROFILE_DOMAIN_V2;
    }

    function feePolicyCompositionDomain() external pure returns (bytes32) {
        return PROGRAMMABLE_COMPOSITION_DOMAIN_V2;
    }

    function canonicalPoolManagerRuntimeCodeHash() external view returns (bytes32) {
        return _canonicalPoolManagerRuntimeCodeHash();
    }

    function canonicalGraphDeployerRuntimeCodeHash() external view returns (bytes32) {
        return _canonicalGraphDeployerRuntimeCodeHash();
    }

    function expectedVaultRuntimeCodeHash() external view returns (bytes32) {
        return _expectedVaultRuntimeCodeHash();
    }

    function expectedTokenRuntimeCodeHash() external view returns (bytes32) {
        return _expectedTokenRuntimeCodeHash();
    }

    function unlockCallback(bytes calldata) external view returns (bytes memory) {
        if (msg.sender != poolManager) revert UnauthorizedPoolManager(msg.sender);
        revert UnexpectedUnlockCallback();
    }

    function _requireEnvironment() internal view {
        if (block.chainid != PROGRAMMABLE_FEE_POLICY_CHAIN_ID_V2) {
            revert UnsupportedFeePolicyChain(block.chainid, PROGRAMMABLE_FEE_POLICY_CHAIN_ID_V2);
        }
        _requireRuntimeCodeHash(poolManager, _canonicalPoolManagerRuntimeCodeHash());
        _requireRuntimeCodeHash(graphDeployer, _canonicalGraphDeployerRuntimeCodeHash());
    }

    function _requireBoundComposition() internal view {
        _requireEnvironment();
        bytes32 hookRuntime = address(this).codehash;
        bytes32 vaultRuntime = address(platformFeeVault).codehash;
        address token = boundToken;
        bytes32 tokenRuntime = token.codehash;
        if (hookRuntime != boundHookRuntimeCodeHash) {
            revert RuntimeCodeHashMismatch(address(this), boundHookRuntimeCodeHash, hookRuntime);
        }
        if (vaultRuntime != boundVaultRuntimeCodeHash) {
            revert RuntimeCodeHashMismatch(address(platformFeeVault), boundVaultRuntimeCodeHash, vaultRuntime);
        }
        if (tokenRuntime != boundTokenRuntimeCodeHash) {
            revert RuntimeCodeHashMismatch(token, boundTokenRuntimeCodeHash, tokenRuntime);
        }
        bytes32 initializerRuntime = authorizedInitializer.codehash;
        if (initializerRuntime != authorizedInitializerRuntimeCodeHash) {
            revert RuntimeCodeHashMismatch(
                authorizedInitializer, authorizedInitializerRuntimeCodeHash, initializerRuntime
            );
        }
        bytes32 actualComposition = _currentCompositionHash();
        if (actualComposition != compositionHash) revert CompositionDrift(compositionHash, actualComposition);
        _validateCustomModule();
    }

    function _currentCompositionHash() private view returns (bytes32) {
        address token = boundToken;
        bytes32 tokenRuntime = token.codehash;
        return programmableCompositionHashV2(
            ProgrammableCompositionV2({
                deploymentProfileHash: deploymentProfileHash,
                hook: address(this),
                hookRuntimeCodeHash: address(this).codehash,
                vault: address(platformFeeVault),
                vaultRuntimeCodeHash: address(platformFeeVault).codehash,
                initializer: authorizedInitializer,
                initializerRuntimeCodeHash: authorizedInitializer.codehash,
                poolId: boundPoolId,
                initialSqrtPriceX96: boundInitialSqrtPriceX96,
                token: token,
                tokenRuntimeCodeHash: tokenRuntime,
                customModule: _customModuleAddress(),
                customModuleRuntimeCodeHash: _customModuleRuntimeCodeHash(),
                customDeltaAccount: address(0),
                maximumCustomDeltaAbsolute: uint128(0)
            })
        );
    }

    function _accrueProgrammablePlatformFee(
        address sender,
        ProgrammablePoolKey calldata key,
        ProgrammableSwapParams calldata params,
        ProgrammableBalanceDelta delta
    ) private returns (int128 platformDelta) {
        if (activePlatformFeeAccrualContextHash != bytes32(0)) {
            revert ReentrantPlatformFeeAccrual();
        }
        bytes32 poolId = keccak256(abi.encode(key));
        bool exactInput = params.amountSpecified < 0;
        bool unspecifiedIsCurrency0 = exactInput != params.zeroForOne;
        int128 unspecifiedDelta = unspecifiedIsCurrency0 ? _amount0(delta) : _amount1(delta);
        ProgrammableCurrency feeCurrency = unspecifiedIsCurrency0 ? key.currency0 : key.currency1;
        uint256 feeBasisAmount;
        if (exactInput) {
            if (unspecifiedDelta < 0) revert UnexpectedUnspecifiedDelta(unspecifiedDelta);
            feeBasisAmount = uint128(unspecifiedDelta);
        } else {
            if (unspecifiedDelta > 0) revert UnexpectedUnspecifiedDelta(unspecifiedDelta);
            feeBasisAmount = _absolute(unspecifiedDelta);
        }
        bytes32 accrualContextHash =
            platformFeeVault.platformFeeAccrualContextHash(poolId, feeCurrency, feeBasisAmount, exactInput);
        if (accrualContextHash == bytes32(0)) revert ReentrantPlatformFeeAccrual();
        activePlatformFeeAccrualContextHash = accrualContextHash;
        uint256 platformFee =
            platformFeeVault.recordPlatformFee(poolId, feeCurrency, feeBasisAmount, exactInput, accrualContextHash);
        if (platformFee > uint128(type(int128).max)) revert UnexpectedUnspecifiedDelta(unspecifiedDelta);
        if (platformFee > 0) {
            IProgrammableV4PoolManagerV1(poolManager)
                .mint(address(platformFeeVault), uint160(ProgrammableCurrency.unwrap(feeCurrency)), platformFee);
        }
        platformFeeVault.confirmPlatformFeeFunding(feeCurrency, platformFee, accrualContextHash);
        activePlatformFeeAccrualContextHash = bytes32(0);
        uint256 grossQualifyingAmount = exactInput ? feeBasisAmount : feeBasisAmount + platformFee;
        emit PlatformFeeAccrued(
            poolId,
            ProgrammableCurrency.unwrap(feeCurrency),
            sender,
            exactInput,
            grossQualifyingAmount,
            platformFee,
            address(platformFeeVault)
        );
        return int128(uint128(platformFee));
    }

    function _afterSwapCustom(
        address,
        ProgrammablePoolKey calldata,
        ProgrammableSwapParams calldata,
        ProgrammableBalanceDelta,
        bytes calldata
    ) internal virtual returns (int128) {
        return 0;
    }

    function _validateCustomModule() internal view virtual;
    function _profileKind() internal view virtual returns (bytes32);
    function _customModuleAddress() internal view virtual returns (address);
    function _customModuleRuntimeCodeHash() internal view virtual returns (bytes32);
    function _expectedVaultRuntimeCodeHash() internal view virtual returns (bytes32);
    function _expectedTokenRuntimeCodeHash() internal view virtual returns (bytes32);
    function _canonicalPoolManagerRuntimeCodeHash() internal view virtual returns (bytes32);
    function _canonicalGraphDeployerRuntimeCodeHash() internal view virtual returns (bytes32);

    function _requireRuntimeCodeHash(address target, bytes32 expected) private view {
        bytes32 actual = target.codehash;
        if (actual != expected) revert RuntimeCodeHashMismatch(target, expected, actual);
    }

    function _checkedAddAfterSwapDelta(int128 customDelta, int128 platformDelta)
        private
        pure
        returns (int128 combinedDelta)
    {
        int256 combined = int256(customDelta) + int256(platformDelta);
        if (combined < type(int128).min || combined > type(int128).max) {
            revert AfterSwapDeltaOverflow(customDelta, platformDelta);
        }
        return int128(combined);
    }

    function _amount0(ProgrammableBalanceDelta delta) private pure returns (int128) {
        return int128(ProgrammableBalanceDelta.unwrap(delta) >> 128);
    }

    function _amount1(ProgrammableBalanceDelta delta) private pure returns (int128) {
        return int128(ProgrammableBalanceDelta.unwrap(delta));
    }

    function _absolute(int128 value) private pure returns (uint256) {
        if (value >= 0) return uint128(value);
        return uint128(-(value + 1)) + 1;
    }
}

contract ProgrammableAdditiveFeeHookV2 is ProgrammableAdditiveFeeHookV2Core {
